import {
    precacheAndRoute,
    createHandlerBoundToURL
} from 'workbox-precaching'
import { NavigationRoute, registerRoute, setCatchHandler } from 'workbox-routing'
import { NetworkFirst, StaleWhileRevalidate, CacheFirst } from 'workbox-strategies'
import { ExpirationPlugin } from 'workbox-expiration'

declare const self: any

// 1. Precache assets generated by build
precacheAndRoute(self.__WB_MANIFEST)

// 2. HTML Document Navigation (NetworkFirst with offline fallback)
// This ensures that when the PWA is closed and opened offline, index.html is served from cache!
registerRoute(
    ({ request, url }) =>
        request.mode === 'navigate' &&
        !url.pathname.startsWith('/api/') &&
        !url.pathname.startsWith('/admin/'),
    new NetworkFirst({
        cacheName: 'app-html-cache',
        networkTimeoutSeconds: 3,
        plugins: [
            new ExpirationPlugin({ maxEntries: 10, maxAgeSeconds: 7 * 24 * 60 * 60 })
        ]
    })
)

// 3. Scripts, Styles & Fonts (StaleWhileRevalidate)
// Caches all JS chunks and stylesheets so the PWA boots and reloads completely offline
registerRoute(
    ({ request, url }) =>
        (request.destination === 'script' || request.destination === 'style' || request.destination === 'font' || request.destination === 'worker') &&
        !url.pathname.startsWith('/api/') &&
        !url.pathname.startsWith('/admin/'),
    new StaleWhileRevalidate({
        cacheName: 'app-static-cache',
        plugins: [
            new ExpirationPlugin({ maxEntries: 500, maxAgeSeconds: 30 * 24 * 60 * 60 })
        ]
    })
)

// 4. Static Images and Icons (CacheFirst)
registerRoute(
    ({ request, url }) =>
        request.destination === 'image' &&
        !url.pathname.startsWith('/api/') &&
        !url.pathname.startsWith('/media/'),
    new CacheFirst({
        cacheName: 'app-images-cache',
        plugins: [
            new ExpirationPlugin({ maxEntries: 100, maxAgeSeconds: 30 * 24 * 60 * 60 })
        ]
    })
)

// 5. Catch handler safety net for offline navigation
setCatchHandler(async ({ request }) => {
    if (request.destination === 'document' || request.mode === 'navigate') {
        const cached = (await caches.match('index.html')) ||
                       (await caches.match('/index.html')) ||
                       (await caches.match('/static/index.html'));
        if (cached) return cached;
    }
    return Response.error();
})

self.addEventListener('install', () => {
    self.skipWaiting()
})

self.addEventListener('activate', (event: any) => {
    event.waitUntil(self.clients.claim())
})


// ==========================================
// PUSH NOTIFICATION
// ==========================================

self.addEventListener(
    'push',
    (event: any) => {

        if (!event.data) {
            return
        }

        let data: {
            notification_id?: number
            title?: string
            message?: string
            url?: string
            image?: string
            tag?: string
            notification_type?: string
        }

        try {
            data = event.data.json()
        } catch {
            data = {
                title: 'Maintenance Tracker',
                message: event.data.text(),
            }
        }

        const title =
            data.title ||
            'Maintenance Tracker'

        let imageUrl = data.image
        if (imageUrl && imageUrl.startsWith('/')) {
            if (self.location.hostname === 'localhost' || self.location.hostname === '127.0.0.1') {
                imageUrl = 'http://localhost:8000' + imageUrl
            } else {
                imageUrl = self.location.origin + imageUrl
            }
        }

        const actions: any[] = []
        const ntype = (data.notification_type || '').toLowerCase()
        if (
            ntype.includes('high priority') ||
            ntype.includes('location approval') ||
            ntype.includes('completed')
        ) {
            actions.push({
                action: 'approve',
                title: 'Approve',
            })
            actions.push({
                action: 'reject',
                title: 'Reject',
            })
        }

        const options: any = {
            body:
                data.message ||
                'You have a new notification.',

            icon: `${import.meta.env.BASE_URL}icon-192x192.png`,

            badge: `${import.meta.env.BASE_URL}ic_stat_notify.png`,

            image: imageUrl || undefined,

            tag: data.tag || undefined,

            renotify: data.tag ? false : undefined, // False so silent updating, or omit for default browser alerts

            actions: actions.length > 0 ? actions : undefined,

            data: {
                notification_id:
                    data.notification_id,

                url: data.url || '/',
            },

            requireInteraction: false,
        }

        event.waitUntil(
            self.registration.showNotification(
                title,
                options
            )
        )
    }
)


// ==========================================
// NOTIFICATION CLICK
// ==========================================

self.addEventListener(
    'notificationclick',
    (event: any) => {
        event.notification.close()

        let targetUrl = event.notification.data?.url || '/'
        const action = event.action

        if (action === 'approve') {
            targetUrl += targetUrl.includes('?') ? '&action=approve' : '?action=approve'
        } else if (action === 'reject') {
            targetUrl += targetUrl.includes('?') ? '&action=reject' : '?action=reject'
        }

        event.waitUntil(
            self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList: any) => {
                for (const client of clientList) {
                    if (client.url.startsWith(self.location.origin)) {
                        return client.navigate(targetUrl).then((c: any) => c.focus())
                    }
                }
                return self.clients.openWindow(targetUrl)
            })
        )
    }
)
